-- TABLE: employees
CREATE TABLE IF NOT EXISTS employees (
  id VARCHAR(255) PRIMARY KEY,
  name VARCHAR(255) NOT NULL,
  matricule VARCHAR(255),
  role VARCHAR(100),
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);


-- TABLE: custom_tool_types
CREATE TABLE IF NOT EXISTS custom_tool_types (
  id VARCHAR(255) PRIMARY KEY,
  type VARCHAR(255) NOT NULL,
  french_designation VARCHAR(255),
  default_name VARCHAR(255),
  default_custom_type VARCHAR(255),
  default_od VARCHAR(255),
  default_min_id VARCHAR(255),
  sort_order INT DEFAULT 0,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);


-- TABLE: wells
CREATE TABLE IF NOT EXISTS wells (
  id VARCHAR(255) PRIMARY KEY,
  name VARCHAR(255) NOT NULL,
  purpose VARCHAR(255),
  completion_type VARCHAR(255),
  reservoir VARCHAR(255),
  field VARCHAR(255),
  state VARCHAR(100),
  perimeter VARCHAR(255),
  spool_prod VARCHAR(255),
  z_sol NUMERIC,
  z_forage NUMERIC,
  z_prod NUMERIC,
  orig_cotes VARCHAR(255),
  sp_att_tbg VARCHAR(255),
  fiche_comments TEXT,
  prod_tbg_od VARCHAR(100),
  prod_tbg_grade VARCHAR(100),
  prod_tbg_weight VARCHAR(100),
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);


-- TABLE: casing_strings
CREATE TABLE IF NOT EXISTS casing_strings (
  id VARCHAR(255) PRIMARY KEY,
  well_id VARCHAR(255) REFERENCES wells(id) ON DELETE CASCADE,
  name VARCHAR(255),
  borehole_size VARCHAR(100),
  casing_size VARCHAR(100),
  top_depth NUMERIC,
  shoe_depth NUMERIC,
  drilled_depth NUMERIC,
  top_of_cement NUMERIC,
  top_of_liner NUMERIC,
  top_of_fonde NUMERIC,
  grade VARCHAR(100),
  weight NUMERIC,
  connection VARCHAR(100),
  observations TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);


-- TABLE: tubing_components
CREATE TABLE IF NOT EXISTS tubing_components (
  id VARCHAR(255) PRIMARY KEY,
  well_id VARCHAR(255) REFERENCES wells(id) ON DELETE CASCADE,
  name VARCHAR(255),
  type VARCHAR(100),
  custom_type VARCHAR(100),
  qty VARCHAR(50),
  od VARCHAR(100),
  length NUMERIC,
  bottom_depth NUMERIC,
  is_cote_product_added BOOLEAN DEFAULT FALSE,
  min_id VARCHAR(100),
  observations TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);


-- TABLE: cement_plugs (Bouchons de Ciment - B.C)
CREATE TABLE IF NOT EXISTS cement_plugs (
  id VARCHAR(255) PRIMARY KEY,
  well_id VARCHAR(255) REFERENCES wells(id) ON DELETE CASCADE,
  top_depth NUMERIC NOT NULL,
  bottom_depth NUMERIC NOT NULL,
  observations TEXT,
  display_order INT DEFAULT 0,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);


-- TABLE: bridge_plugs (Barrières de Fond - B.P)
CREATE TABLE IF NOT EXISTS bridge_plugs (
  id VARCHAR(255) PRIMARY KEY,
  well_id VARCHAR(255) REFERENCES wells(id) ON DELETE CASCADE,
  designation VARCHAR(255) DEFAULT 'Bridge plug',
  size VARCHAR(100) DEFAULT '7"',
  type VARCHAR(100) DEFAULT 'PERMANENT',
  length NUMERIC DEFAULT 0,
  bottom_depth NUMERIC NOT NULL,
  observations TEXT,
  display_order INT DEFAULT 0,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- TABLE: perforation_zones
CREATE TABLE IF NOT EXISTS perforation_zones (
  id VARCHAR(255) PRIMARY KEY,
  well_id VARCHAR(255) REFERENCES wells(id) ON DELETE CASCADE,
  top_depth NUMERIC,
  bottom_depth NUMERIC,
  perforation_type VARCHAR(100),
  diameter VARCHAR(100),
  density NUMERIC,
  phasing VARCHAR(100),
  shots_count INT,
  reservoir VARCHAR(255),
  is_squeezed BOOLEAN DEFAULT FALSE,
  observations TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);


-- TABLE: well_history
CREATE TABLE IF NOT EXISTS well_history (
  id VARCHAR(255) PRIMARY KEY,
  well_id VARCHAR(255) REFERENCES wells(id) ON DELETE CASCADE,
  folio VARCHAR(50),
  snapshot JSONB,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);


